"""Each original worked example: all scalar intermediate operations."""
CASES={}
def case(ch,i,strategy,steps):CASES[(ch,i)]=dict(strategy=strategy,steps=[dict(target=k,expression=e,unit=u,why=w) for k,e,u,w in steps])
case(1,1,r'El equilibrio exige $L=mg$, $T=D$. Primero hallar $q$ y peso; después $C_L=W/(qS)$, resistencia $D=qSC_D$ y potencia al eje $P_e=DV/\eta_p$.',[
('q','1.06*55**2/2','Pa','Calcular presión dinámica a la velocidad prescrita.'),('W','920*9.80665','N','Convertir masa a peso.'),('CL','W/(q*16)','','Despejar coeficiente de sustentación.'),('D','q*16*.038','N','Convertir coeficiente de resistencia en fuerza.'),('Pu','D*55','W','Potencia útil contra resistencia.'),('Pe','Pu/.78','W','Dividir por rendimiento para la potencia al eje.')])
case(2,1,r'La potencia específica divide potencia disponible por masa. Es un indicador parcial: el dato de control en tres ejes requiere evidencia distinta y no se deduce de ese cociente.',[
('A','10000/260','W/kg','Convertir kW a W y dividir por masa de A.'),('B','18000/310','W/kg','Repetir para B con sus propios datos.')])
case(3,1,r'Obtener densidades con el gas ideal a la misma presión y temperatura. Arquímedes compensa peso del helio, estructura y carga; al dividir por gravedad, la masa adicional es $(\rho_a-\rho_{He})V-m_s-m_c$.',[
('rhoa','85000/(287.05287*285)','kg/m**3','Densidad de aire exterior.'),('rhoHe','85000/(2077.1*285)','kg/m**3','Densidad de helio.'),('mnet','(rhoa-rhoHe)*180','kg','Restar masa de gas de la masa de aire desplazada.'),('mextra','mnet-90-60','kg','Descontar estructura y la carga ya embarcada.')])
case(4,1,r'Integrar hidrostática con $T=T_0-\beta h$ y gas ideal da $p=p_0(T/T_0)^{g_0/(R\beta)}$. Después cerrar densidad y calcular sonido para el Mach.',[
('T','288.15-.0065*4500','K','Temperatura local.'),('p','101325*(T/288.15)**(9.80665/(287.05287*.0065))','Pa','Presión de la misma capa.'),('rho','p/(287.05287*T)','kg/m**3','Gas ideal local.'),('a','sqrt(1.4*287.05287*T)','m/s','Sonido adiabático a temperatura estática.'),('Ma','140/a','','Mach con la velocidad de ensayo prescrita.')])
case(5,1,r'La estimación de base de nube usa diferencia de temperaturas, para la que grados Celsius y kelvin tienen el mismo incremento. A 1 km, se aplica por separado el gradiente de la parcela seca y el ambiental.',[
('LCL','125*(23-11)','m','Aplicar la correlación docente suministrada.'),('Tparcel','23-9.8','degC','Temperatura de la parcela a 1 km.'),('Tenv','23-6.5','degC','Temperatura ambiental a la misma altura.'),('difference','(23-9.8)-(23-6.5)','K','Comparar parcela con ambiente; un valor negativo indica parcela más fría en este modelo.')])
case(6,1,r'Primero separar viscosidad dinámica de cinemática: $\nu=\mu/\rho$. Reynolds usa la cuerda y la velocidad de ensayo; presión dinámica es otra magnitud.',[
('nu','1.84e-5/1.18','m**2/s','Calcular viscosidad cinemática.'),('Re','28*.65/nu','','Comparar inercia y viscosidad con longitud cuerda.'),('q','1.18*28**2/2','Pa','Calcular presión dinámica por separado.')])
case(7,1,r'Continuidad obtiene velocidad de salida. Bernoulli horizontal calcula su presión. Solo entonces el balance de momento permite hallar la fuerza de pared sobre el fluido; la fuerza del fluido sobre el conducto tiene signo opuesto.',[
('U2','.12*22/.06','m/s','Conservar caudal volumétrico.'),('mdot','1.19*.12*22','kg/s','Caudal másico de entrada.'),('p2','3200+1.19*(22**2-U2**2)/2','Pa','Despejar presión manométrica de salida.'),('Fpressure','3200*.12-p2*.06','N','Fuerza neta de las dos caras de presión.'),('Fwall','mdot*(U2-22)-Fpressure','N','Restar las fuerzas de presión del cambio de flujo de momento.'),('Ffluid','-Fwall','N','Aplicar acción y reacción para la fuerza sobre el conducto.')])
case(8,1,r'El choque normal conserva masa, momento y entalpía total, pero genera entropía. Se calculan razones de presión y densidad, se usa gas ideal para la razón térmica y después se evalúa la diferencia de entropía.',[
('pr','1+2*1.4/(1.4+1)*(2**2-1)','','Razón de presiones del choque normal.'),('rr','(1.4+1)*2**2/((1.4-1)*2**2+2)','','Razón de densidades por conservación.'),('Tr','pr/rr','','La ecuación de estado relaciona ambas razones.'),('p2','24000*pr','Pa','Presión posterior.'),('T2','220*Tr','K','Temperatura posterior.'),('M2','sqrt((1+.2*2**2)/(1.4*2**2-.2))','','Mach posterior subsónico.'),('ds','1.4*287.05287/.4*log(Tr)-287.05287*log(pr)','J/(kg*K)','Entropía positiva; no usar relaciones isentrópicas a través del choque.')])
case(9,1,r'La ley lineal del perfil usa el ángulo relativo al de sustentación nula en radianes. La fuerza y el par se obtienen con sus referencias de cuerda. Para el centro de presión, igualar el momento de la resultante al par respecto al centro aerodinámico.',[
('dalph','(4-(-2))*pi/180','rad','Convertir el intervalo angular.'),('q','1.05*45**2/2','Pa','Presión dinámica.'),('cl','2*pi*dalph','','Ley de sustentación del perfil.'),('lift','q*1.4*cl','N/m','Sustentación por envergadura.'),('moment','q*1.4**2*(-.060)','N','Momento por envergadura, negativo de picado.'),('xratio','.25-(-.060)/cl','','Aislar posición relativa del centro de presión.'),('xcp','xratio*1.4','m','Convertir posición relativa a distancia.'),('Re','1.05*45*1.4/1.75e-5','','Comprobar escala viscosa.')])
case(10,1,r'La geometría determina $S$ y $AR$. La inducción modifica la pendiente, de modo que el ángulo fija $C_L$ del ala. Con el peso impuesto, ese coeficiente determina velocidad; por último, polar y presión dinámica determinan resistencia.',[
('S','14*2.4*(1+.45)/2','m**2','Sumar las dos semialas trapezoidales.'),('AR','14**2/S','','Alargamiento.'),('a','6/(1+6/(pi*.9*AR))','1/rad','Pendiente tridimensional.'),('CL','a*(4-(-2))*pi/180','','Coeficiente correspondiente al ángulo.'),('K','1/(pi*.9*AR)+.008','','Sumar resistencia inducida y término cuadrático de perfil.'),('V','sqrt(2*40000/(.95*S*CL))','m/s','Despejar velocidad del equilibrio de sustentación.'),('q','.95*V**2/2','Pa','Presión dinámica compatible.'),('D','q*S*(.028+K*CL**2)','N','Evaluar resistencia total.')])
case(10,2,r'Derivar $E=C_L/(C_{D0}+KC_L^2)$ e imponer derivada nula da $C_{D0}=KC_L^2$. Se iguala el término cuadrático total, que incluye la parte de perfil, no solo la resistencia inducida aislada.',[
('CL','sqrt(.028/.0519571)','','Óptimo positivo de eficiencia.'),('CD','.028+.0519571*CL**2','','Coeficiente total en el óptimo.'),('E','CL/CD','','Máxima eficiencia.'),('V','sqrt(2*40000/(.95*24.36*CL))','m/s','Velocidad correspondiente a ese equilibrio.'),('D','40000/E','N','Mínima resistencia.'),('induced','.0439571*CL**2','','Comparar el término inducido con el cuadrático total.')])
case(11,1,r'En vuelo nivelado, sustituir $C_L=W/(qS)$ en la polar da $D=AV^2+B/V^2$. Imponer $D=T_A$, multiplicar por $V^2$ y resolver la cuadrática en $V^2$. Se comprueba además pérdida y el Mach límite del modelo.',[
('A','.95*24.36*.028/2','kg/m','Coeficiente parásito.'),('B','2*.0519571*40000**2/(.95*24.36)','N*m**2/s**2','Coeficiente inversamente cuadrático.'),('disc','3800**2-4*A*B','N**2','Comprobar discriminante.'),('Vlo','sqrt(2*B/(3800+sqrt(disc)))','m/s','Raíz lenta calculada sin cancelación.'),('Vhi','sqrt((3800+sqrt(disc))/(2*A))','m/s','Raíz rápida.'),('Vs','sqrt(2*40000/(.95*24.36*1.4))','m/s','Límite de pérdida.'),('Vlimit','.30*sqrt(1.4*287.05287*275)','m/s','Convertir Mach límite a TAS con temperatura local.')])
case(11,2,r'El giro tiene aceleración aunque la rapidez sea constante. Equilibrio vertical fija $n=1/\cos\phi$; la componente horizontal da el radio. Se comprueban por separado sustentación y resistencia al aumentar la carga.',[
('n','1/cos(30*pi/180)','','Factor de carga de giro.'),('r','55**2/(9.80665*tan(30*pi/180))','m','Radio por aceleración centrípeta.'),('qS','.95*55**2*24.36/2','N','Fuerza de referencia a 55 m/s.'),('CL','n*40000/qS','','Sustentación requerida en giro.'),('D','qS*(.028+.0519571*CL**2)','N','Resistencia del mismo estado de giro.'),('margin','4000-D','N','Margen de empuje; comparar además CL con 1.4.')])
case(11,3,r'Con eficiencia y TAS constantes, $dW/dt=-g_0c_mW/E$. Separar $dW/W=-(g_0c_m/E)dt$ e integrar entre pesos da tiempo logarítmico. La distancia usa TAS constante y la masa consumida se obtiene dividiendo diferencia de pesos por gravedad.',[
('t','15/(9.80665*1.6e-5)*log(36000/33000)','s','Evaluar la integral temporal.'),('R','100*t','m','Multiplicar por velocidad constante.'),('fuel','(36000-33000)/9.80665','kg','Convertir peso perdido en masa consumida.')])
case(12,1,r'Calcular margen estático y pendiente de momento. Para trim, imponer $0=C_{m0}+C_{m\alpha}\alpha+C_{m\delta}\delta$, pasar los dos primeros términos al otro lado y dividir por pendiente de mando.',[
('SM','.40-.28','','Separación CG--punto neutro.'),('Cma','-4.8*SM','1/rad','Pendiente estática restauradora.'),('alpha','5*pi/180','rad','Convertir el ángulo antes de usar pendientes por radián.'),('delta','-(.060+Cma*alpha)/(-.800)','rad','Despejar elevador con su signo.'),('degrees','delta*180/pi','degree','Convertir solo la respuesta final a grados.')])
case(13,1,r'Las fuerzas de frenado del modelo dependen de velocidad terrestre prescrita, mientras el dato de aproximación es aéreo. Primero hacer la suma vectorial longitudinal del viento; separar demora a velocidad constante y frenado uniforme.',[
('Vhead','32-6','m/s','Con viento de cara la velocidad terrestre es menor.'),('Vtail','32+6','m/s','Con viento de cola es mayor.'),('delayhead','Vhead*1.5','m','Recorrido previo al frenado con cara.'),('brakehead','Vhead**2/(2*2.2)','m','Integrar frenado uniforme desde la velocidad terrestre.'),('shead','delayhead+brakehead','m','Sumar fases del caso con cara.'),('stail','Vtail*1.5+Vtail**2/(2*2.2)','m','Repetir ambas fases con cola.')])
case(14,1,r'El viento del norte apunta hacia el sur. Para mantener derrota este, la componente aérea norte debe ser +20 m/s: $55\cos\psi-20=0$. Resolver el ángulo y usar la componente este para tiempo de ruta.',[
('psi','acos(20/55)*180/pi','degree','Elegir rumbo que compense el viento procedente del norte.'),('Ve','sqrt(55**2-20**2)','m/s','Obtener componente este por Pitágoras.'),('t','100000/Ve','s','Convertir 100 km a m y dividir por velocidad terrestre de la ruta.')])
case(15,1,r'La gravedad $\mu/r^2$ proporciona aceleración centrípeta $v^2/r$. Despejar $v=\sqrt{\mu/r}$ y usar longitud orbital $2\pi r$ para periodo. La ingravidez aparente corresponde a caída libre, no gravedad nula.',[
('r','(6371+500)*1000','m','Sumar radio terrestre y altura antes de convertir km.'),('v','sqrt(3.986004418e14/r)','m/s','Velocidad circular.'),('P','2*pi*r/v','s','Tiempo de una vuelta.'),('g','3.986004418e14/r**2','m/s**2','Gravedad local.'),('F','100*g','N','Fuerza gravitatoria sobre el satélite.')])
case(15,2,r'La transferencia es una elipse con periapsis en la órbita inferior y apoapsis en la superior. Su semieje mayor es la media de radios. Vis-viva proporciona velocidades de la elipse; cada impulso es la diferencia con la velocidad circular local.',[
('at','(6871000+7371000)/2','m','Semieje mayor de transferencia.'),('vc1','sqrt(3.986004418e14/6871000)','m/s','Velocidad circular inferior.'),('vp','sqrt(3.986004418e14*(2/6871000-1/at))','m/s','Velocidad de transferencia en periapsis.'),('vc2','sqrt(3.986004418e14/7371000)','m/s','Velocidad circular superior.'),('va','sqrt(3.986004418e14*(2/7371000-1/at))','m/s','Velocidad de transferencia en apoapsis.'),('dv1','vp-vc1','m/s','Primer impulso progrado.'),('dv2','vc2-va','m/s','Segundo impulso para circularizar.'),('t','pi*sqrt(at**3/3.986004418e14)','s','La transferencia recorre media órbita elíptica.')])
case(16,1,r'La carga exterior a una sección tiene resultante $w(L-x)$ y brazo $(L-x)/2$, luego $M=w(L-x)^2/2$. La tensión extrema usa $Mc/I$. Integrar $EIv\prime\prime=M$ con flecha y giro nulos en raíz da $v_L=wL^4/(8EI)$.',[
('M','3000*4**2/2','N*m','Momento de raíz por equilibrio.'),('sigma','M*.15/2e-4','Pa','Tensión en la fibra más alejada.'),('v','3000*4**4/(8*70e9*2e-4)','m','Flecha de voladizo con rigidez constante.'),('relative','v/4','','Comparar flecha con longitud para la hipótesis geométrica.')])
case(17,1,r'La condición activa de rigidez es $\delta=NL/(EA)=\delta_{max}$. Despejar área de cada material, calcular volumen y masa, y comprobar la tensión que resulta de esa área.',[
('AA','12000*1.2/(70e9*.0006)','m**2','Área mínima elástica de A.'),('AB','12000*1.2/(120e9*.0006)','m**2','Área de B con su propio módulo.'),('mA','2700*AA*1.2','kg','Densidad por volumen de A.'),('mB','1600*AB*1.2','kg','Densidad por volumen de B.'),('sA','12000/AA','Pa','Tensión resultante de A.'),('sB','12000/AB','Pa','Tensión resultante de B.'),('saving','1-mB/mA','','Reducción de masa bajo el único criterio de rigidez.')])
case(18,1,r'Un ciclo de cuatro tiempos ocupa dos vueltas: la frecuencia de ciclos es $n/2$. El trabajo de un ciclo es $p_{me}V_d$. Después se propagan potencia y par por el reductor y por la hélice, cada uno con su rendimiento.',[
('n','2400/60','1/s','Convertir rpm a vueltas por segundo.'),('Pb','900000*.006*n/2','W','Trabajo por ciclo por ciclos por segundo.'),('mf','Pb/(.30*43e6)','kg/s','Despejar combustible del rendimiento al freno.'),('Cm','Pb/(2*pi*n)','N*m','Potencia dividida por velocidad angular.'),('nh','n/1.5','1/s','Velocidad de giro tras reducción.'),('Ph','.97*Pb','W','Potencia tras pérdidas de engranajes.'),('Ch','Ph/(2*pi*nh)','N*m','Par de la hélice.'),('Pu','.80*Ph','W','Potencia útil propulsiva.')])
case(19,1,r'El combustible añade caudal a la salida. Se conserva esa masa tanto en el balance de momento como en la energía cinética. La eficiencia global compara potencia útil con aporte químico; no se identifica con rendimiento propulsivo.',[
('mf','.020*25','kg/s','Caudal de combustible por relación combustible/aire.'),('mg','25+mf','kg/s','Caudal total saliente.'),('F','mg*600-25*200','N','Balance axial de momento.'),('Pu','F*200','W','Potencia útil al vuelo.'),('Ek','(mg*600**2-25*200**2)/2','W','Aumento de energía cinética de las corrientes.'),('Pchem','mf*43e6','W','Aporte químico.'),('etao','Pu/Pchem','','Eficiencia global.'),('TSFC','mf/F','kg/(N*s)','Consumo por empuje.'),('Fapprox','25*(600-200)','N','Comparación que desprecia masa de combustible.')])
case(20,1,r'El empuje suma momento y presión residual. Su cociente con caudal define velocidad efectiva. Como la masa decrece linealmente, integrar $dv=Fdt/(m_0-\dot mt)$ da $\Delta v=c\ln(m_0/m_f)$; no se divide el impulso entre una masa arbitraria.',[
('F','5*2500+20000*.020','N','Empuje completo con presión.'),('c','F/5','m/s','Velocidad efectiva, distinta de velocidad de salida.'),('Isp','c/9.80665','s','Impulso específico convencional.'),('tb','(1000-600)/5','s','Duración del consumo.'),('I','F*tb','N*s','Impulso total a empuje constante.'),('dv','c*log(1000/600)','m/s','Integral de aceleración con masa variable.'),('a0','F/1000','m/s**2','Aceleración al inicio.'),('af','F/600','m/s**2','Aceleración al final.')])
case(21,1,r'La cámara de extensión actúa sobre el pistón completo y la de retorno sobre el área anular. El equilibrio resta contrapresión y rozamiento. Continuidad da velocidad y caudal de retorno; el suministro de bomba se evalúa en su propia frontera.',[
('Ap','pi*.050**2/4','m**2','Área completa de pistón.'),('Aa','pi*(.050**2-.020**2)/4','m**2','Restar sección del vástago.'),('QA','6e-3/60','m**3/s','Convertir litros por minuto.'),('Fu','12e6*Ap-1e6*Aa-800','N','Fuerza útil al equilibrio.'),('v','QA/Ap','m/s','Velocidad por continuidad de entrada.'),('QB','Aa*v','m**3/s','Caudal de la cámara anular.'),('Pin','12e6*QA/.85','W','Potencia de eje necesaria en la bomba.'),('Pu','Fu*v','W','Potencia que recibe la carga.')])
case(22,1,r'La batería aporta tensión por capacidad, dando Wh. Aplicar fracción utilizable y rendimiento de conversión antes de dividir por cargas. El cálculo local de línea usa corriente estimada a tensión nominal y no vuelve a descontar pérdidas ya incluidas globalmente.',[
('En','28*24','Wh','Energía nominal.'),('Euse','En*.75*.90','Wh','Energía entregable a barra.'),('P','180+120+60','W','Sumar cargas paralelas.'),('t','Euse/P','h','Wh dividido entre W entrega horas.'),('I','180/28','A','Corriente nominal estimada de la línea principal.'),('dV','I*.08','V','Caída óhmica.'),('PR','I**2*.08','W','Calentamiento de línea; contrastar con I por caída.')])
case(23,1,r'En cada estado, dividir momento de masa total entre masa total. Consumir elimina masa y su momento; transferir mantiene masa total y altera momento en $\Delta m(x_{destino}-x_{origen})$.',[
('M0','2000+200+300','kg','Masa inicial.'),('S0','2000*2.5+200*1+300*4','kg*m','Momento inicial respecto al datum.'),('x0','S0/M0','m','Centro inicial.'),('M1','M0-100','kg','Masa tras consumo delantero.'),('S1','S0-100*1','kg*m','Restar el momento de la masa consumida.'),('x1','S1/M1','m','Centro después del consumo.'),('S2','S1+40*(1-4)','kg*m','Trasladar 40 kg desde el depósito trasero al delantero.'),('x2','S2/M1','m','La transferencia conserva la masa total.')])
case(24,1,r'El caudal capturado es eficiencia de captura por contenido líquido por flujo de volumen interceptado. El balance térmico suma calor sensible del agua y convección; la eficacia de entrega divide la demanda eléctrica.',[
('mw','.70*.00040*80*.12','kg/s','Convertir contenido líquido de g/m3 a kg/m3.'),('dT','5-(-10)','K','Diferencia térmica igual en kelvin y Celsius.'),('Pw','mw*4180*dT','W','Calor sensible del agua capturada.'),('Pc','80*.50*dT','W','Pérdida convectiva de la superficie.'),('Pe','(Pw+Pc)/.85','W','Entrada eléctrica con eficacia menor que uno.'),('Platent','mw*334000','W','Comparación aislada con fusión de hielo a cero grados; no es el proceso principal.')])
case(25,1,r'Comparar siempre potencias a la misma frontera. La fuente limitada a 30 kW solo entrega $0.92P_s$ a la barra; el déficit de barra determina energía útil de batería y su rendimiento determina energía extraída.',[
('Pbus','12000+8000+4000','W','Demanda normal de barra.'),('Pin','Pbus/.92','W','Demanda de entrada a la fuente.'),('margin','30000-Pin','W','Margen referido a entrada.'),('Pavailable','.92*30000','W','Máxima potencia entregable a la barra.'),('deficit','Pbus+6000-Pavailable','W','Déficit transitorio en la misma frontera.'),('E','deficit*20/.90','J','Energía extraída del almacenamiento.'),('Ewh','E/3600','Wh','Convertir joules a Wh para comparar capacidad.')])
